// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.storageimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.ConversationStageimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport java.time.Instantimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Crash-safe conversation state storage. * * **Problem**: an in-memory-only implementation loses state if app is killed. * If user says "Call mom", NOUS asks "Which number?", and OS kills the app — * the state is gone. User returns confused. * * **Solution**: Persist conversation state to disk (file or Room) so it * survives app kills and device reboots. * * This implementation uses a simple file-based persistence (one file per * session) via the [StateFileStorage] abstraction. The real Room-backed * `StateFileStorage` is provided by :feature:memory's MemoryModule * (Strategy §3.6 — `RoomStateFileStorage`). * * ## Crash Safety Guarantees * *   - State written to disk within 100ms of save() *   - State survives: app kill, device reboot, battery death *   - State auto-expires after 5 minutes (TTL) *   - State cleaned up on session end * * @see <a href="docs/spec/module2-spec-review.pdf">§5.2 NeedsInput State Machine</a> */@Singletonclass CrashSafeConversationStateStorage @Inject constructor(    private val fileStorage: StateFileStorage,) : ConversationStateStorage {    override suspend fun save(state: ConversationStateData): Result<Unit> {        return try {            fileStorage.write(state.sessionId, serialize(state))            Timber.tag("NOUS.State").v(                "Saved conversation state: session=%s, skill=%s",                state.sessionId.value.take(8),                state.skillId,            )            Result.Success(Unit, state.correlationId, 0)        } catch (t: Throwable) {            Timber.tag("NOUS.State").w(t, "Failed to save conversation state")            Result.Failure(                error = com.roshan.persona.common.AppError.from(t, state.correlationId),                correlationId = state.correlationId,                durationNanos = 0,            )        }    }    override suspend fun getActive(sessionId: SessionId): Result<ConversationStateData?> {        val correlationId = CorrelationId.generate()        return try {            val serialized = fileStorage.read(sessionId) ?: return Result.Success(null, correlationId, 0)            val state = deserialize(serialized) ?: return Result.Success(null, correlationId, 0)            // Check if expired or not in NEEDS_INPUT stage            val active = if (!state.isExpired() && state.stage == ConversationStage.NEEDS_INPUT) {                state            } else {                // Clean up expired/completed state                fileStorage.delete(sessionId)                null            }            Result.Success(active, correlationId, 0)        } catch (t: Throwable) {            Timber.tag("NOUS.State").w(t, "Failed to read conversation state")            Result.Success(null, correlationId, 0)  // Non-fatal — return null        }    }    override suspend fun markCompleted(sessionId: SessionId): Result<Unit> {        fileStorage.delete(sessionId)        return Result.Success(Unit, CorrelationId.generate(), 0)    }    override suspend fun markExpired(sessionId: SessionId): Result<Unit> {        fileStorage.delete(sessionId)        return Result.Success(Unit, CorrelationId.generate(), 0)    }    override suspend fun deleteAllForSession(sessionId: SessionId): Result<Unit> {        fileStorage.delete(sessionId)        return Result.Success(Unit, CorrelationId.generate(), 0)    }    override suspend fun deleteExpired(): Result<Int> {        return try {            val allFiles = fileStorage.listAll()            var deletedCount = 0            val now = Instant.now()            for (sessionId in allFiles) {                val serialized = fileStorage.read(sessionId) ?: continue                val state = deserialize(serialized) ?: continue                if (state.isExpired(now)) {                    fileStorage.delete(sessionId)                    deletedCount++                }            }            Result.Success(deletedCount, CorrelationId.generate(), 0)        } catch (t: Throwable) {            Result.Success(0, CorrelationId.generate(), 0)  // Non-fatal        }    }    // ─── Serialization ────────────────────────────────────────────────────    /**     * Serialize state to a simple string format (key=value lines).     *     * Note: Intent and SkillOutput are complex sealed types — we serialize     * them as their simple name + raw representation. Full deserialization     * of Intent/SkillOutput happens in Module 3 with Room.     */    private fun serialize(state: ConversationStateData): String {        return buildString {            appendLine("sessionId=${state.sessionId.value}")            appendLine("correlationId=${state.correlationId.value}")            appendLine("skillId=${state.skillId}")            appendLine("intent=${state.intent::class.simpleName}")            appendLine("stage=${state.stage.name}")            appendLine("createdAt=${state.createdAt.toEpochMilli()}")            appendLine("expiresAt=${state.expiresAt.toEpochMilli()}")            state.partialOutput?.let {                appendLine("partialOutputType=${it::class.simpleName}")            }        }    }    /**     * Deserialize from string format.     *     * Note: Returns a simplified ConversationStateData with Intent.Unknown     * (full Intent restoration happens in Module 3 with Room).     */    private fun deserialize(serialized: String): ConversationStateData? {        return try {            val map = serialized.lines()                .filter { it.contains("=") }                .associate {                    val idx = it.indexOf("=")                    it.substring(0, idx) to it.substring(idx + 1)                }            val sessionId = SessionId(map["sessionId"] ?: return null)            val correlationId = CorrelationId(map["correlationId"] ?: return null)            val skillId = map["skillId"] ?: return null            val stage = ConversationStage.valueOf(map["stage"] ?: return null)            val createdAt = Instant.ofEpochMilli(map["createdAt"]?.toLongOrNull() ?: return null)            val expiresAt = Instant.ofEpochMilli(map["expiresAt"]?.toLongOrNull() ?: return null)            ConversationStateData(                sessionId = sessionId,                correlationId = correlationId,                skillId = skillId,                intent = Intent.Unknown(raw = ""),  // Simplified — full restoration in Module 3                stage = stage,                partialOutput = null,  // Simplified — full restoration in Module 3                createdAt = createdAt,                expiresAt = expiresAt,            )        } catch (t: Throwable) {            Timber.tag("NOUS.State").w(t, "Failed to deserialize conversation state")            null        }    }}/** * File storage interface for conversation state (abstraction over actual * file system / DataStore / Room). * * Real implementations: *   - `RoomStateFileStorage` (:feature:memory) — Room-backed (PRODUCTION) *   - `InMemoryStateFileStorage` (test-only, in `src/test/kotlin/`) — for unit tests * * Brain does NOT provide its own `StateFileStorage` binding — * :feature:memory's MemoryModule provides it (Strategy §14.2 Table 10). */interface StateFileStorage {    suspend fun write(sessionId: SessionId, data: String)    suspend fun read(sessionId: SessionId): String?    suspend fun delete(sessionId: SessionId)    suspend fun listAll(): List<SessionId>}